function BookCoverBoardEdgeTrimmerMaker.init() BookCoverBoardEdgeTrimmerMaker.ironStock=18; BookCoverBoardEdgeTrimmerMaker.bronzeStock=14; BookCoverBoardEdgeTrimmerMaker.woodStock=10; BookCoverBoardEdgeTrimmerMaker.leatherStock=8; BookCoverBoardEdgeTrimmerMaker.silverStock=8; BookCoverBoardEdgeTrimmerMaker.goldStock=6; BookCoverBoardEdgeTrimmerMaker.jewelStock=4; BookCoverBoardEdgeTrimmerMaker.pearlStock=4; BookCoverBoardEdgeTrimmerMaker.productStock={}; BookCoverBoardEdgeTrimmerMaker.buildings={}; BookCoverBoardEdgeTrimmerMaker.maker=nil; BookCoverBoardEdgeTrimmerMaker.activeMaking={}; BookCoverBoardEdgeTrimmerMaker.totalProducts=0; BookCoverBoardEdgeTrimmerMaker.dayTimer=0; print("[BookCoverBoardEdgeTrimmerMaker] Royal Book Cover Board Edge Trimmer Maker System initialized (6 products, 4 buildings)") end
function BookCoverBoardEdgeTrimmerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverBoardEdgeTrimmerMaker.maker={name=n or ("Obrezovalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obrezovalec najet: %s (spretnost: %d)",BookCoverBoardEdgeTrimmerMaker.maker.name,s),"success") end; return true end
function BookCoverBoardEdgeTrimmerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverBoardEdgeTrimmerMaker.build(id) local ok,e=BookCoverBoardEdgeTrimmerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverBoardEdgeTrimmerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverBoardEdgeTrimmerMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverBoardEdgeTrimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverBoardEdgeTrimmerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverBoardEdgeTrimmerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverBoardEdgeTrimmerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverBoardEdgeTrimmerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverBoardEdgeTrimmerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverBoardEdgeTrimmerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverBoardEdgeTrimmerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverBoardEdgeTrimmerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverBoardEdgeTrimmerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverBoardEdgeTrimmerMaker.buildings==0 then return false,"Potrebna obrezovalna delavnica" end; if not BookCoverBoardEdgeTrimmerMaker.maker then return false,"Potreben obrezovalec" end; return true end
function BookCoverBoardEdgeTrimmerMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverBoardEdgeTrimmerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverBoardEdgeTrimmerMaker.ironStock=BookCoverBoardEdgeTrimmerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverBoardEdgeTrimmerMaker.bronzeStock=BookCoverBoardEdgeTrimmerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverBoardEdgeTrimmerMaker.woodStock=BookCoverBoardEdgeTrimmerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverBoardEdgeTrimmerMaker.leatherStock=BookCoverBoardEdgeTrimmerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverBoardEdgeTrimmerMaker.silverStock=BookCoverBoardEdgeTrimmerMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverBoardEdgeTrimmerMaker.goldStock=BookCoverBoardEdgeTrimmerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverBoardEdgeTrimmerMaker.jewelStock=BookCoverBoardEdgeTrimmerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverBoardEdgeTrimmerMaker.pearlStock=BookCoverBoardEdgeTrimmerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverBoardEdgeTrimmerMaker.maker then t=math.max(1,t-math.floor(BookCoverBoardEdgeTrimmerMaker.maker.skill/13)) end; table.insert(BookCoverBoardEdgeTrimmerMaker.activeMaking,{id="bookcoverboardedgetrimmer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverBoardEdgeTrimmerMaker.completeMaking(m) local q=1.0+(BookCoverBoardEdgeTrimmerMaker.getQualityBonus()/100); if BookCoverBoardEdgeTrimmerMaker.maker then q=q+(BookCoverBoardEdgeTrimmerMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverBoardEdgeTrimmerMaker.productStock[m.productType]=(BookCoverBoardEdgeTrimmerMaker.productStock[m.productType] or 0)+m.quantity; BookCoverBoardEdgeTrimmerMaker.totalProducts=BookCoverBoardEdgeTrimmerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverBoardEdgeTrimmerMaker.maker then BookCoverBoardEdgeTrimmerMaker.maker.itemsMade=BookCoverBoardEdgeTrimmerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverBoardEdgeTrimmerMaker.maker.skill=math.min(100,BookCoverBoardEdgeTrimmerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obrezovalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverboardedgetrimmer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverBoardEdgeTrimmerMaker.update(dt) if not _G.state then return end; BookCoverBoardEdgeTrimmerMaker.dayTimer=BookCoverBoardEdgeTrimmerMaker.dayTimer+dt; if BookCoverBoardEdgeTrimmerMaker.dayTimer>=30 then BookCoverBoardEdgeTrimmerMaker.dayTimer=0; for i=#BookCoverBoardEdgeTrimmerMaker.activeMaking,1,-1 do local m=BookCoverBoardEdgeTrimmerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverBoardEdgeTrimmerMaker.completeMaking(m); table.remove(BookCoverBoardEdgeTrimmerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverBoardEdgeTrimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverBoardEdgeTrimmerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
